-- 캐릭터 정보를 캐릭터 1명 = 1행으로 모은 테이블입니다(스키마 재검토 전 임시 통합본).
-- 프론트 src/config/ 의 characters·characterBaseStats·characterWeapons·characterEchoSets·
-- characterValidOptions·characterRecommendations 에서 생성했습니다.
-- 목록형 정보는 JSONB로 원본 모양 그대로 담았습니다.
CREATE TABLE chara_info (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    rarity SMALLINT NOT NULL CHECK (rarity BETWEEN 1 AND 5),
    element VARCHAR(10) NOT NULL,
    weapon_type VARCHAR(10),
    image_path VARCHAR(255),
    status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'HIDDEN', 'UPCOMING')),
    sort_order INT NOT NULL,

    -- 기초 스탯 (90레벨 기준, 데이터 없으면 NULL)
    base_hp NUMERIC(10, 2),
    base_atk NUMERIC(10, 2),
    base_def NUMERIC(10, 2),
    base_energy_regen NUMERIC(6, 2),
    base_crit_rate NUMERIC(6, 2),
    base_crit_dmg NUMERIC(6, 2),

    innate_bonuses JSONB NOT NULL DEFAULT '[]',          -- [{"category": "크리티컬", "value": 8}, ...]
    valid_options JSONB NOT NULL DEFAULT '[]',           -- ["크리티컬%", "공격력%", ...]
    recommended_weapon_ids JSONB NOT NULL DEFAULT '[]',  -- ["verdant-summit", ...]
    echo_set_combos JSONB NOT NULL DEFAULT '[]',         -- [[{"setId": "sierra-gale", "pieceCount": 5}], ...]
    recommendation JSONB                                 -- 이잘키 추천(무기·에코 주옵·치명 비율·참고사항 등)
);

